    <div class="product-image-placeholder d-flex align-items-center justify-content-center bg-light">
        <span class="text-muted text-center p-2">@Product.Name</span>
    </div>
    <div class="card-body d-flex flex-column">
        <h5 class="card-title text-truncate" title="@Product.Name">@Product.Name</h5>
        <p class="card-text fw-bold fs-5 text-primary mb-1">@Product.Price.ToString("C")</p>
        <div class="product-rating mb-2" title="@($"{Product.Rating:F1} out of 5")">@GetStarRating()</div>
        @if (!Product.InStock)
        {
            <span class="badge bg-danger mb-2">Out of Stock</span>
        }
        <button class="btn btn-primary btn-sm mt-auto"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCart"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public Product Product { get; set; } = default!;

    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    [Parameter]
    public EventCallback<Product> OnAddToCart { get; set; }

    private async Task HandleCardClick()
    {
        await OnProductSelected.InvokeAsync(Product);
    }

    private async Task HandleAddToCart()
    {
        await OnAddToCart.InvokeAsync(Product);
    }

    private string GetStarRating()
    {
        var filled = (int)Math.Round(Product.Rating);
        var empty = 5 - filled;
        return new string('★', filled) + new string('☆', empty);
    }
}
"}

